# Parse all .md files
def parse_md(path):
    text = open(path, encoding='utf-8').read()
    meta = {}
    # Control field table
    for m in re.finditer(r'\|\s*([A-Za-z ]+?)\s*\|\s*(.*?)\s*\|', text):
        k = m.group(1).strip().lower().replace(' ', '_')
        v = m.group(2).strip()
        if k in ('portfolio_key','evidence_role','immutable_entity','referenced_revision','current_revision','matter'):
            meta[k] = v
    # record id from title
    m = re.search(r'CB-DOC-061-(\d+)', text)
    if m:
        meta['record_id'] = 'CB-DOC-061-' + m.group(1)
    # subject from heading
    m = re.search(r'^#\s+(.+?)\s+—\s+CB-DOC-061-(\d+)', text)
    if m:
        meta['subject'] = m.group(1).strip()
    return meta

# Parse all .json files
def parse_json(path):
    d = json.load(open(path, encoding='utf-8'))
    return {
        'record_id': d.get('record_id'),
        'portfolio_key': d.get('portfolio_key'),
        'evidence_role': d.get('evidence_role'),
        'immutable_entity_key': d.get('immutable_entity_key'),
        'referenced_revision': d.get('referenced_revision'),
        'current_revision': d.get('current_revision'),
        'subject': d.get('subject'),
    }

recs = {}
for path in sorted(glob.glob(os.path.join(base, "*", "*_source_export.md"))):
    meta = parse_md(path)
    recs[meta.get('record_id')] = meta
for path in sorted(glob.glob(os.path.join(base, "*", "*_source_export.json"))):
    meta = parse_json(path)
    recs[meta.get('record_id')] = meta

print("Total records parsed:", len(recs))
from collections import defaultdict
by_key = defaultdict(list)
for rid, meta in sorted(recs.items()):
    pk = meta.get('portfolio_key', '?')
